/**
 * The Hebrew text of every perek, for the perek-test email and landing page (docs/PARENT_VERIFICATION.md §6.1).
 * worker/data/text.json is generated by scripts/build_data.py from the same data as public/data/m; the client test
 * tests/textData.test.ts guards against drift.
 */
import raw from "../data/text.json";

export interface MasechtaText {
  /** The public/data/m file this was generated from. */
  source: string;
  he: string;
  en: string;
  /** perakim["1"][mishnahIndex][pieceIndex] = chunk.he */
  perakim: Record<string, string[][]>;
}

const TEXT = raw as unknown as Record<string, MasechtaText>;

export function masechtaText(id: string): MasechtaText | null {
  return Object.prototype.hasOwnProperty.call(TEXT, id) ? (TEXT[id] ?? null) : null;
}

/** Number of perakim in the masechta; 0 when unknown. */
export function perakimCount(id: string): number {
  const m = masechtaText(id);
  return m ? Object.keys(m.perakim).length : 0;
}

/** The perek's pieces, mishnah by mishnah; [] when unknown. */
export function perekPieces(id: string, perek: number): string[][] {
  return masechtaText(id)?.perakim[String(perek)] ?? [];
}

export function masechtaIds(): string[] {
  return Object.keys(TEXT);
}
